from pathlib import Path

def replace(path, old, new):
    p = Path(path)
    s = p.read_text()
    if old not in s:
        raise SystemExit(f'missing patch anchor in {path}: {old[:80]!r}')
    p.write_text(s.replace(old, new, 1))

